import Detail from "./components/detail";
import WorkLog from "./components/workLog";
import UploadFile from "./components/uploadFile";

import {mapGetters} from 'vuex'
import {orderList, orderRemove, orderRecover, month} from "@/api/safeDanger/report"

import BatchImport from '../rectification/components/batchImport'
import ImportTable from '../rectification/components/importTable'
import {release} from '@/api/safeDanger/rectificationImport'
import {categoryTree} from "@/api/safeDanger/hiddenCategory"

// import { list, del } from "@/api/safeDanger/computerroom";
export default {
  // 隐患提报
  name: "index",
  computed: {
    ...mapGetters(["userInfo","userDetail"]),
    recoverDis() {
      // 当前工单带99（市级） 不带99（县级）
      return !(this.multipleSelection.length == 1 && this.multipleSelection[0] && ((this.multipleSelection[0].secondCompany.slice(-2) == '99' && this.multipleSelection[0].status == 1) || (this.multipleSelection[0].secondCompany.slice(-2) != '99' && this.multipleSelection[0].status == 8)))
    }
  },
  components: {
    Detail,
    UploadFile,
    WorkLog,
    BatchImport,
    ImportTable
  },
  data() {
    return {

      defaultProps: {
        value: 'orgId',
        label: 'shortName',
        leaf: 'leaf',
        children: 'shortNameVOList',
        // checkStrictly: true,
        emitPath: false,
        expandTrigger: 'hover'
      },

      worklogVisible: false,

      tableHeight: undefined,
      // 查询参数
      queryParams: {
        current: 1,
        size: 20,
        isPresent: 0,
        newType: 0,
        serialNumber: undefined,
        hiddenCategory: undefined,
        status: undefined,
        content: undefined,
        hiddenSource: undefined,
        secondCompany: undefined,
        hiddenCategoryName: undefined
      },
      queryDisabled: {
        showDeviceType: true,
        showUnitSecond: false
      },
      // 用户表格数据
      tableList: null,
      // 总条数
      total: 0,
      // 选中数据
      multipleSelection: [],
      rectificationMethodList: [],
      // 选中数组
      ids: [],
      // 遮罩层
      loading: true,
      // 弹框层
      isEdit: false,
      isInfo: false,
      detailId: undefined,
      workflowId: undefined,
      dialogTitle: '',
      dialogVisible: false,
      dialogVisibleOld: false,
      // 下拉列表
      hiddenSourceList: [],
      firstCategoryList: [],
      yearList: [
        '2023',
        '2024'
      ],

      statusList: [],
      basicUnitSeconds: [],
      claimStatusList: [
        {
          dictValue: 0,
          dictLabel: '未认领'
        },
        {
          dictValue: 1,
          dictLabel: '已认领'
        },
      ],


      // 导入弹框
      upload: {
        open: false // 是否显示弹出层（用户导入）
      },
      importTableVisible: false,
      importTable: [],
    }
  },
  created() {
    this.initData()
    this.getList();
  },
  mounted() {
    this.getCurrentHeight()
    window.addEventListener('resize', this.getCurrentHeight)
    window.addEventListener('webkitvisibilitychange', this.getCurrentHeight)
  },
  methods: {
    handleOrderRecover() {
      orderRecover({id: this.multipleSelection[0].id}).then(res => {
        if (res.code == 200) {
          this.getList();
          this.msgSuccess('操作成功！');
        }
      })
    },
    onImportSubmit(data) {
      if (!data) return
      this.upload.open = false
      this.importTable = data
      this.importTableVisible = true
    },
    // 提交上传文件
    submitFileForm() {
      this.$refs.upload.submitFileForm()
    },

    initData() {
      this.getDicts('hidden_source').then(response => {
        this.hiddenSourceList = response.data
      });

      // 隐患分类
      categoryTree().then(response => { // 一级
        this.firstCategoryList = response.data
      })


      this.getDicts('hidden_present_status').then(response => {
        this.statusList = response.data
      });
      this.getDicts('rectification_method').then(response => { //整改方式
        this.rectificationMethodList = response.data
      });
      // month().then(res => {
      //   this.yearList = res.data;
      // });
      // queryShortNameList({ parentId: this.companyCode.slice(0, 4) }).then(response => {
      //   this.basicUnitSeconds = response.data
      // })
      // queryShortNameTree().then(res=>{
      //   console.log(88, res)
      //   this.basicUnitSeconds = res.data.shortNameVOList
      //   this.queryParams.secondCompany = this.companyCode
      // })
      // this.deptSelect()
    },
    // 获取 二、三级单位及部门
    // deptSelect(){
    //   queryTowThreeDpet().then(response => {
    //     let datas = response.data
    //     datas.towDept.forEach(ele=>{
    //       ele.children = datas.threeDept
    //     })
    //     this.basicUnitSeconds = datas.towDept
    //   })
    // },
    getList() {
      this.loading = true
      orderList(this.queryParams).then(response => {
        this.tableList = response.data.records
        this.total = response.data.total
        this.loading = false
      })
    },
    handleSelectionChange(val) {
      this.ids = []
      this.multipleSelection = val;
      this.ids = val.map(item => item.id);
    },
    /** 搜索按钮操作 */
    handleQuery() {
      this.queryParams.current = 1
      this.getList();
    },
    /** 重置按钮操作 */
    resetQuery() {
      this.resetForm("queryForm");
      this.handleQuery();
    },
    handleDelete() {
      // let flag = this.multipleSelection.some(el => el.claimStatus == 0)
      let flag = this.multipleSelection.some(el => el.newType == 1)
      if (flag) {
        this.$message({
          message: '导入工单不可删除！',
          type: 'warning'
        })
        return
      }

      const ids = this.ids;
      this.$confirm('是否确认删除选中数据项?', "警告", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        return orderRemove(ids);
      }).then(rsp => {
        if (rsp.code == 200) {
          this.getList();
          this.msgSuccess('删除成功');
        }
      }).catch(function () {
      });
    },
    handleAdd() {
      this.detailId = undefined
      this.dialogTitle = '新增'
      this.dialogVisible = true
      this.isEdit = false
      this.isInfo = false
    },
    handleUpdate() {
      if (this.multipleSelection.length <= 0 || this.multipleSelection.length > 1) {
        this.$message({
          message: '请选择一条需要修改记录！',
          type: 'warning'
        });
        return;
      }
      if (this.multipleSelection[0].status > 0 && this.multipleSelection[0].status != 10) {
        this.$message({
          message: '流程已发起,不可编辑!',
          type: 'warning'
        });
        return;
      }


      //新版本
      this.detailId = this.multipleSelection[0].id;
      this.dialogTitle = '编辑';
      this.dialogVisible = true;
      this.isEdit = true
      this.isInfo = false
      // if (this.multipleSelection[0].version == "1.0.0") { //老版本
      //   this.detailId = this.multipleSelection[0].id;
      //   this.dialogTitle = '编辑';
      //   this.dialogVisibleOld = true;
      //   this.isEdit = true
      //   this.isInfo = false
      // } else { //新版本
      //   this.detailId = this.multipleSelection[0].id;
      //   this.dialogTitle = '编辑';
      //   this.dialogVisible = true;
      //   this.isEdit = true
      //   this.isInfo = false
      // }

    },
    exportExcel() {
      this.$confirm('全量数据导出较慢，请耐心等待。', '警告', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        const loading = this.$loading({
          lock: true,
          text: '正在处理，请稍等。。。',
          spinner: 'el-icon-loading',
        });
        this.download('/msdp-hiddendanger/order/export', {
          ...this.queryParams
        }, `隐患记录工单${this.formatDate(new Date(), 'yyyy-MM-dd-hh:mm:ss')}.xlsx`, loading)
      }).catch(function () {
      })
    },
    checkLog() {
      this.detailId = this.multipleSelection[0].id;
      this.workflowId = this.multipleSelection[0].workflowId
      this.worklogVisible = true
    },
    handleDblclick(row) {
      this.detailId = row.id;
      this.dialogTitle = '详情';
      this.dialogVisible = true;
      this.isEdit = false
      this.isInfo = true
      // if (row.version == "1.0.0") { //老版本
      //   this.detailId = row.id;
      //   this.dialogTitle = '详情';
      //   this.dialogVisibleOld = true;
      //   this.isEdit = false
      //   this.isInfo = true
      // } else { //新版本
      //   this.detailId = row.id;
      //   this.dialogTitle = '详情';
      //   this.dialogVisible = true;
      //   this.isEdit = false
      //   this.isInfo = true
      // }
    },
    closeDialog() {
      this.importTableVisible = false
      this.dialogVisible = false
      // this.dialogVisibleOld = false
      this.getList();

      // 刷新待办工作菜单数量
      this.$store.dispatch('hiddenTotal')
    },

    // 格式化数据
    formatHiddenSource(row) {
      return this.selectDictLabel(this.hiddenSourceList, row.hiddenSource)
    },
    formatState(row) {
      // if (row.isRefuteCancel == '1') {
      //   return '已终止'
      // }
      return this.selectDictLabel(this.statusList, row.status)
    },
    formatClaimStatus(row) {
      return this.selectDictLabel(this.claimStatusList, row.claimStatus)
    },

    formatSecondCompany(row) {
      if (!row.secondCompany) return ''
      let data = this.basicUnitSeconds;
      // if(row.secondCompany.toString().length == 5){
      //   data = this.basicUnitSeconds;
      // }else{
      //   data = this.basicUnitSeconds[0].children;
      // }
      for (let i = 0; i < data.length; i++) {
        if (row.secondCompany == data[i].orgId) {
          return data[i].shortName;
        }
      }
    },

    getStatusColor(row) {
      return 't_class'
    },

    //导入
    importExcel2() {
      this.upload.open = true
    },
    handleUpdate2() {
      // if (this.multipleSelection[0].newType != 1 || this.multipleSelection[0].releaseStatus != 0) {
      //   this.$message({
      //     message: '仅导入后未发布工单可修改！',
      //     type: 'warning'
      //   })
      //   return
      // }

      // if (this.multipleSelection[0].status != 7) {
      //   this.$message({
      //     message: '已发起审批！当前数据无法操作！',
      //     type: 'warning'
      //   })
      //   return
      // }
      this.detailId = this.multipleSelection[0].id
      this.dialogTitle = '编辑'
      this.dialogVisible = true
      this.isEdit = true
      this.isInfo = false

    },
    handleDelete2() {
      let flag = this.multipleSelection.some(el => el.newType != 1 || el.releaseStatus != 0 || el.status != 7 || el.claimStatus != 0)
      if (flag) {
        this.$message({
          message: '仅导入后未发布未认领工单可删除！',
          type: 'warning'
        })
        return
      }

      const ids = this.ids
      this.$confirm('是否确认删除选中数据项?', '警告', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        return orderRemove(ids)
      }).then(rsp => {
        this.getList()
        this.msgSuccess('删除成功')
      }).catch(function () {
      })
    },
    handleAdd2() {
      release(this.ids).then(res => {
        this.$message.success(res.msg)
        this.getList()
      })
    },


    // 获取自适应高度
    getCurrentHeight() {
      let windowHeight = window.innerHeight //窗口高度
      this.tableHeight = (windowHeight - 335) + 'px'
    },
  }
}
